package com.shipflow.order;
import com.shipflow.common.exception.GlobalExceptionHandler; import com.shipflow.order.api.ShipmentOrderController; import com.shipflow.order.api.model.ShipmentOrderResponse; import com.shipflow.order.application.ShipmentOrderApplicationService; import com.shipflow.security.SecurityConfig; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.context.TestConfiguration; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.context.annotation.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.oauth2.jwt.JwtDecoder; import org.springframework.test.web.servlet.MockMvc; import java.math.*; import java.time.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(ShipmentOrderController.class) @Import({SecurityConfig.class,GlobalExceptionHandler.class,ShipmentOrderControllerWebMvcTest.Config.class}) class ShipmentOrderControllerWebMvcTest { @Autowired MockMvc mvc; @MockBean ShipmentOrderApplicationService service; @TestConfiguration static class Config{@Bean JwtDecoder jwtDecoder(){return t->{throw new org.springframework.security.oauth2.jwt.BadJwtException("test");};}} @Test void createsOrderForTenant() throws Exception {when(service.create(eq(7L),eq(2L),eq(99L),any(),eq("k"),isNull())).thenReturn(new ShipmentOrderResponse(88L,"SO1",99L,"DRAFT",new BigDecimal("12"),"USD",new BigDecimal("2"),OffsetDateTime.parse("2026-08-11T08:00:00Z")));mvc.perform(post("/api/v1/quotes/99/shipment-orders").with(jwt().jwt(t->t.subject("2").claim("tenant_id","7")).authorities(new SimpleGrantedAuthority("scope:TENANT"))).with(csrf()).header("Idempotency-Key","k").contentType("application/json").content("{\"senderAddress\":{\"contactName\":\"A\",\"phone\":\"1\",\"countryCode\":\"CN\",\"city\":\"SZ\",\"addressLine1\":\"x\",\"postalCode\":\"1\"},\"receiverAddress\":{\"contactName\":\"B\",\"phone\":\"2\",\"countryCode\":\"US\",\"city\":\"LA\",\"addressLine1\":\"x\",\"postalCode\":\"2\"},\"items\":[{\"sku\":\"s\",\"productName\":\"p\",\"quantity\":1,\"unitPrice\":1,\"currency\":\"USD\"}]}" )).andExpect(status().isCreated()).andExpect(jsonPath("$.data.id").value(88));}}
